export type LessonContent = {
  overview: string;
  explanation: string;
  application: string;
  example: string;
  takeaways: string[];
  question: string;
  answer: string;
  source?: { label: string; url: string };
};

const lesson = (
  overview: string,
  explanation: string,
  application: string,
  example: string,
  takeaways: string[],
  question: string,
  answer: string,
  source?: LessonContent['source'],
): LessonContent => ({ overview, explanation, application, example, takeaways, question, answer, source });

